content:
* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  font-family: system-ui, -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, Oxygen, Ubuntu, Cantarell, 'Open Sans', 'Helvetica Neue', sans-serif;
  background-color: #05050f;
  color: #f0f0f5;
  overflow: hidden;
  height: 100vh;
  width: 100vw;
}

.app-container {
  position: relative;
  width: 100vw;
  height: 100vh;
  display: flex;
  flex-direction: column;
  overflow: hidden;
}

.header {
  position: absolute;
  top: 0;
  left: 0;
  right: 0;
  height: 60px;
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 0 24px;
  background: rgba(10, 10, 25, 0.75);
  backdrop-filter: blur(10px);
  border-bottom: 1px solid rgba(255, 255, 255, 0.1);
  z-index: 10;
}

.title {
  font-size: 1.25rem;
  font-weight: 700;
  letter-spacing: 0.05em;
  background: linear-gradient(135deg, #6ee7b7, #3b82f6, #9333ea);
  -webkit-background-clip: text;
  -webkit-text-fill-color: transparent;
}

.controls {
  display: flex;
  align-items: center;
  gap: 12px;
}

.btn {
  background: rgba(255, 255, 255, 0.1);
  border: 1px solid rgba(255, 255, 255, 0.2);
  color: #ffffff;
  padding: 6px 14px;
  border-radius: 6px;
  cursor: pointer;
  font-size: 0.85rem;
  font-weight: 500;
  transition: all 0.2s ease;
  backdrop-filter: blur(5px);
  will-change: transform, background-color, border-color;
}

.btn:hover {
  background: rgba(255, 255, 255, 0.2);
  border-color: rgba(255, 255, 255, 0.4);
  transform: translateY(-1px);
}

.btn:active {
  transform: translateY(0);
}

.canvas-container {
  position: absolute;
  top: 0;
  left: 0;
  width: 100vw;
  height: 100vh;
  z-index: 1;
}

.info-panel {
  position: absolute;
  top: 80px;
  right: 24px;
  width: 320px;
  background: rgba(15, 15, 30, 0.85);
  backdrop-filter: blur(12px);
  border: 1px solid rgba(255, 255, 255, 0.15);
  border-radius: 12px;
  padding: 20px;
  z-index: 10;
  box-shadow: 0 10px 30px rgba(0, 0, 0, 0.5);
  animation: fadeIn 0.3s ease-out;
  will-change: transform, opacity;
}

.planet-list {
  position: absolute;
  bottom: 24px;
  left: 50%;
  transform: translateX(-50%);
  display: flex;
  gap: 10px;
  background: rgba(10, 10, 25, 0.8);
  backdrop-filter: blur(10px);
  padding: 12px 16px;
  border-radius: 16px;
  border: 1px solid rgba(255, 255, 255, 0.1);
  z-index: 10;
  max-width: 90vw;
  overflow-x: auto;
  scrollbar-width: thin;
  scrollbar-color: rgba(255, 255, 255, 0.2) rgba(0, 0, 0, 0.1);
}

.planet-list::-webkit-scrollbar {
  height: 6px;
}

.planet-list::-webkit-scrollbar-track {
  background: rgba(0, 0, 0, 0.1);
  border-radius: 3px;
}

.planet-list::-webkit-scrollbar-thumb {
  background: rgba(255, 255, 255, 0.2);
  border-radius: 3px;
}

.planet-list::-webkit-scrollbar-thumb:hover {
  background: rgba(255, 255, 255, 0.4);
}

.planet-card {
  display: flex;
  flex-direction: column;
  align-items: center;
  padding: 8px 12px;
  background: rgba(255, 255, 255, 0.05);
  border: 1px solid rgba(255, 255, 255, 0.1);
  border-radius: 10px;
  cursor: pointer;
  transition: all 0.2s ease;
  min-width: 70px;
  will-change: transform, background-color, border-color;
}

.planet-card:hover {
  background: rgba(255, 255, 255, 0.15);
  border-color: rgba(255, 255, 255, 0.3);
  transform: translateY(-2px);
}

.planet-name {
  font-size: 0.75rem;
  font-weight: 600;
  color: #d1d5db;
  margin-top: 4px;
  white-space: nowrap;
}

@keyframes fadeIn {
  from {
    opacity: 0;
    transform: translateY(10px);
  }
  to {
    opacity: 1;
    transform: translateY(0);
  }
}

@media (max-width: 768px) {
  .info-panel {
    top: 70px;
    right: 12px;
    left: 12px;
    width: auto;
    padding: 16px;
  }

  .header {
    padding: 0 12px;
    height: 56px;
  }

  .title {
    font-size: 1rem;
  }

  .controls {
    gap: 8px;
  }

  .btn {
    padding: 4px 10px;
    font-size: 0.75rem;
  }

  .planet-list {
    bottom: 16px;
    padding: 8px 12px;
  }
}

/** 惑星の識別子を表すユニオン型 */
export type PlanetId = 'mercury' | 'venus' | 'earth' | 'mars' | 'jupiter' | 'saturn' | 'uranus' | 'neptune';

/** 衛星データの型定義（将来拡張用） */
export interface MoonData {
  /** 衛星の一意識別子 */
  id: string;
  /** 衛星の名前 */
  name: string;
  /** 衛星の半径（km単位） */
  radius: number;
  /** 母惑星からの距離 */
  distance: number;
}

/** 惑星データの型定義 */
export interface PlanetData {
  /** 惑星の一意識別子 */
  id: PlanetId | string;
  /** 惑星の名称 */
  name: string;
  /** 3D描画用のカラーコード（例: '#8c8c8c'） */
  color: string;
  /** 3Dシーン上での表示サイズ（相対値） */
  size: number;
  /** 太陽からの距離（シミュレーション上のスケール単位） */
  distance: number;
  /** 公転速度の係数 */
  speed: number;
  /** 実際の半径（km単位） */
  radius: number;
  /** 惑星の詳細な説明文 */
  description: string;
  /** 自転速度の係数 */
  rotationSpeed: number;
  /** 軌道傾斜角（度、将来拡張用） */
  orbitalInclination?: number;
  /** 保有する衛星のリスト（将来拡張用） */
  moons?: MoonData[];
}

import { useEffect, useRef } from 'react';
import * as THREE from 'three';
import { PlanetData } from '../types';

interface SolarSystemViewerProps {
  planets: PlanetData[];
  selectedPlanetId: string | null;
  onSelectPlanet: (id: string) => void;
  speedMultiplier: number;
}

/** 太陽系3Dシーンとアニメーションを管理するカスタムフック */
function useSolarSystemScene(
  containerRef: React.RefObject<HTMLDivElement | null>,
  planets: PlanetData[],
  selectedPlanetId: string | null,
  onSelectPlanet: (id: string) => void,
  speedMultiplier: number
) {
  const planetsRef = useRef<PlanetData[]>(planets);
  planetsRef.current = planets;
  const selectedPlanetIdRef = useRef<string | null>(selectedPlanetId);
  selectedPlanetIdRef.current = selectedPlanetId;
  const speedMultiplierRef = useRef<number>(speedMultiplier);
  speedMultiplierRef.current = speedMultiplier;

  const planetMeshesRef = useRef<{ [key: string]: THREE.Mesh }>({});

  useEffect(() => {
    const container = containerRef.current;
    if (!container) return;

    // シーン初期化
    const scene = new THREE.Scene();

    // カメラ初期化
    const camera = new THREE.PerspectiveCamera(
      60,
      window.innerWidth / window.innerHeight,
      0.1,
      1000
    );
    camera.position.set(0, 40, 70);
    camera.lookAt(0, 0, 0);

    // レンダラー初期化
    const renderer = new THREE.WebGLRenderer({ antialias: true, alpha: true });
    renderer.setSize(window.innerWidth, window.innerHeight);
    renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
    container.appendChild(renderer.domElement);

    // ライティング
    const ambientLight = new THREE.AmbientLight(0x333333);
    scene.add(ambientLight);

    const sunLight = new THREE.PointLight(0xffffff, 2, 300);
    sunLight.position.set(0, 0, 0);
    scene.add(sunLight);

    // 管理用dispose配列
    const geometriesToDispose: THREE.BufferGeometry[] = [];
    const materialsToDispose: THREE.Material[] = [];

    // 背景の星
    const starsGeometry = new THREE.BufferGeometry();
    geometriesToDispose.push(starsGeometry);
    const starsCount = 1500;
    const starPositions = new Float32Array(starsCount * 3);
    for (let i = 0; i < starsCount * 3; i++) {
      starPositions[i] = (Math.random() - 0.5) * 400;
    }
    starsGeometry.setAttribute('position', new THREE.BufferAttribute(starPositions, 3));
    const starsMaterial = new THREE.PointsMaterial({ color: 0xffffff, size: 0.7 });
    materialsToDispose.push(starsMaterial);
    const starField = new THREE.Points(starsGeometry, starsMaterial);
    scene.add(starField);

    // 太陽 (中心)
    const sunGeometry = new THREE.SphereGeometry(4, 32, 32);
    geometriesToDispose.push(sunGeometry);
    const sunMaterial = new THREE.MeshBasicMaterial({ color: 0xffaa00 });
    materialsToDispose.push(sunMaterial);
    const sunMesh = new THREE.Mesh(sunGeometry, sunMaterial);
    scene.add(sunMesh);

    // 惑星メッシュの作成
    planetMeshesRef.current = {};
    const angles: { [key: string]: number } = {};

    planetsRef.current.forEach((planet) => {
      angles[planet.id] = Math.random() * Math.PI * 2;
      const geometry = new THREE.SphereGeometry(planet.size, 32, 32);
      geometriesToDispose.push(geometry);

      const material = new THREE.MeshStandardMaterial({
        color: planet.color,
        roughness: 0.7,
        metalness: 0.2,
      });
      materialsToDispose.push(material);

      const mesh = new THREE.Mesh(geometry, material);
      mesh.userData = { id: planet.id };
      scene.add(mesh);
      planetMeshesRef.current[planet.id] = mesh;

      // 軌道線
      const orbitPoints = [];
      for (let i = 0; i <= 64; i++) {
        const theta = (i / 64) * Math.PI * 2;
        orbitPoints.push(
          new THREE.Vector3(
            Math.cos(theta) * planet.distance,
            0,
            Math.sin(theta) * planet.distance
          )
        );
      }
      const orbitGeometry = new THREE.BufferGeometry().setFromPoints(orbitPoints);
      geometriesToDispose.push(orbitGeometry);

      const orbitMaterial = new THREE.LineBasicMaterial({
        color: 0xffffff,
        transparent: true,
        opacity: 0.15,
      });
      materialsToDispose.push(orbitMaterial);

      const orbitLine = new THREE.Line(orbitGeometry, orbitMaterial);
      scene.add(orbitLine);
    });

    // レイキャスター (クリック判定)
    const raycaster = new THREE.Raycaster();
    const mouse = new THREE.Vector2();

    const handlePointerDown = (event: PointerEvent) => {
      mouse.x = (event.clientX / window.innerWidth) * 2 - 1;
      mouse.y = -(event.clientY / window.innerHeight) * 2 + 1;

      raycaster.setFromCamera(mouse, camera);
      const meshes = Object.values(planetMeshesRef.current);
      const intersects = raycaster.intersectObjects(meshes);

      if (intersects.length > 0) {
        const intersectedMesh = intersects[0].object as THREE.Mesh;
        const planetId = intersectedMesh.userData.id;
        if (planetId) {
          onSelectPlanet(planetId);
        }
      }
    };

    window.addEventListener('pointerdown', handlePointerDown);

    // リサイズ処理
    const handleResize = () => {
      camera.aspect = window.innerWidth / window.innerHeight;
      camera.updateProjectionMatrix();
      renderer.setSize(window.innerWidth, window.innerHeight);
    };

    window.addEventListener('resize', handleResize);

    // アニメーションループ
    let animationFrameId: number;
    const clock = new THREE.Clock();

    const animate = () => {
      animationFrameId = requestAnimationFrame(animate);
      const delta = clock.getDelta();

      planetsRef.current.forEach((planet) => {
        const mesh = planetMeshesRef.current[planet.id];
        if (mesh) {
          angles[planet.id] += planet.speed * speedMultiplierRef.current * delta * 0.5;
          const x = Math.cos(angles[planet.id]) * planet.distance;
          const z = Math.sin(angles[planet.id]) * planet.distance;
          mesh.position.set(x, 0, z);
          mesh.rotation.y += planet.rotationSpeed * delta * speedMultiplierRef.current;
        }
      });

      // 選択された惑星にカメラを追従させるか、デフォルト位置にする
      if (selectedPlanetIdRef.current && planetMeshesRef.current[selectedPlanetIdRef.current]) {
        const targetMesh = planetMeshesRef.current[selectedPlanetIdRef.current];
        const targetPos = targetMesh.position;
        camera.position.x += (targetPos.x + 10 - camera.position.x) * 0.05;
        camera.position.y += (targetPos.y + 6 - camera.position.y) * 0.05;
        camera.position.z += (targetPos.z + 15 - camera.position.z) * 0.05;
        camera.lookAt(targetPos);
      }

      renderer.render(scene, camera);
    };

    animate();

    return () => {
      window.removeEventListener('pointerdown', handlePointerDown);
      window.removeEventListener('resize', handleResize);
      cancelAnimationFrame(animationFrameId);

      // メモリリーク防止のための明示的なdispose処理
      geometriesToDispose.forEach((geometry) => geometry.dispose());
      materialsToDispose.forEach((material) => material.dispose());

      renderer.dispose();
      if (renderer.domElement && container.contains(renderer.domElement)) {
        container.removeChild(renderer.domElement);
      }
    };
  }, [containerRef, onSelectPlanet]);
}

export default function SolarSystemViewer({
  planets = [],
  selectedPlanetId,
  onSelectPlanet,
  speedMultiplier = 1,
}: SolarSystemViewerProps) {
  const containerRef = useRef<HTMLDivElement>(null);

  useSolarSystemScene(
    containerRef,
    planets,
    selectedPlanetId,
    onSelectPlanet,
    speedMultiplier
  );

  return <div className="canvas-container" ref={containerRef} />;
}

import { useState } from 'react';
import SolarSystemViewer from './components/SolarSystemViewer';
import { PLANETS_DATA } from './constants/planets';
import './index.css';

export default function App() {
  const [selectedPlanetId, setSelectedPlanetId] = useState<string | null>(null);
  const [speedMultiplier, setSpeedMultiplier] = useState<number>(1);

  const selectedPlanet = PLANETS_DATA.find((p) => p.id === selectedPlanetId);

  const handleSelectPlanet = (id: string) => {
    setSelectedPlanetId(id);
  };

  const handleResetCamera = () => {
    setSelectedPlanetId(null);
  };

  const handleSpeedChange = (multiplier: number) => {
    setSpeedMultiplier(multiplier);
  };

  return (
    <div className="app-container">
      <header className="header">
        <h1 className="title">太陽系 3D シミュレーション</h1>
        <div className="controls">
          <button 
            className="btn" 
            onClick={() => handleSpeedChange(0.5)}
            aria-label="シミュレーション速度を0.5倍にする"
          >
            0.5x
          </button>
          <button 
            className="btn" 
            onClick={() => handleSpeedChange(1)}
            aria-label="シミュレーション速度を等倍にする"
          >
            1x
          </button>
          <button 
            className="btn" 
            onClick={() => handleSpeedChange(2)}
            aria-label="シミュレーション速度を2倍にする"
          >
            2x
          </button>
          <button 
            className="btn" 
            onClick={handleResetCamera}
            aria-label="視点を全体表示にリセットする"
          >
            全体視点
          </button>
        </div>
      </header>

      <SolarSystemViewer
        planets={PLANETS_DATA}
        selectedPlanetId={selectedPlanetId}
        onSelectPlanet={handleSelectPlanet}
        speedMultiplier={speedMultiplier}
      />

      {selectedPlanet && (
        <div className="info-panel" role="region" aria-label={`${selectedPlanet.name}の詳細情報`}>
          <h2 style={{ fontSize: '1.25rem', marginBottom: '8px', color: selectedPlanet.color }}>
            {selectedPlanet.name}
          </h2>
          <p style={{ fontSize: '0.85rem', color: '#9ca3af', marginBottom: '12px' }}>
            半径: {selectedPlanet.radius.toLocaleString()} km
          </p>
          <p style={{ fontSize: '0.9rem', lineHeight: 1.5, color: '#e5e7eb' }}>
            {selectedPlanet.description}
          </p>
          <button
            className="btn"
            style={{ marginTop: '16px', width: '100%' }}
            onClick={() => setSelectedPlanetId(null)}
            aria-label="詳細情報を閉じる"
          >
            閉じる
          </button>
        </div>
      )}

      <div className="planet-list" role="region" aria-label="惑星選択リスト">
        {PLANETS_DATA.map((planet) => (
          <div
            key={planet.id}
            className="planet-card"
            onClick={() => handleSelectPlanet(planet.id)}
            role="button"
            tabIndex={0}
            aria-label={`${planet.name}を選択`}
            style={{
              borderColor: selectedPlanetId === planet.id ? planet.color : undefined,
            }}
          >
            <div
              style={{
                width: '16px',
                height: '16px',
                borderRadius: '50%',
                backgroundColor: planet.color,
              }}
            />
            <span className="planet-name">{planet.name}</span>
          </div>
        ))}
      </div>
    </div>
  );
}
